CREATE TABLE "acuerdos_suministro" ("id" TEXT NOT NULL PRIMARY KEY,"empresaId" TEXT NOT NULL DEFAULT '1',"numero" TEXT NOT NULL,"proveedorId" TEXT NOT NULL,"titulo" TEXT NOT NULL,"moneda" TEXT NOT NULL DEFAULT 'PEN',"tipoCambio" DECIMAL NOT NULL DEFAULT 1,"vigenteDesde" DATETIME NOT NULL,"vigenteHasta" DATETIME NOT NULL,"estado" TEXT NOT NULL DEFAULT 'ACTIVO',"usuarioId" TEXT NOT NULL,"usuarioNombre" TEXT NOT NULL,"creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "acuerdos_suministro_proveedorId_fkey" FOREIGN KEY ("proveedorId") REFERENCES "proveedores"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "acuerdos_suministro_empresaId_numero_key" ON "acuerdos_suministro"("empresaId","numero");
CREATE TABLE "acuerdo_suministro_lineas" ("id" TEXT NOT NULL PRIMARY KEY,"acuerdoId" TEXT NOT NULL,"insumoId" TEXT NOT NULL,"cantidadComprometida" DECIMAL NOT NULL,"cantidadLiberada" DECIMAL NOT NULL DEFAULT 0,"precioUnitario" DECIMAL NOT NULL,CONSTRAINT "acuerdo_suministro_lineas_acuerdoId_fkey" FOREIGN KEY ("acuerdoId") REFERENCES "acuerdos_suministro"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "acuerdo_suministro_lineas_insumoId_fkey" FOREIGN KEY ("insumoId") REFERENCES "insumos"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "acuerdo_suministro_lineas_acuerdoId_insumoId_key" ON "acuerdo_suministro_lineas"("acuerdoId","insumoId");
ALTER TABLE "ordenes_compra" ADD COLUMN "acuerdoId" TEXT REFERENCES "acuerdos_suministro"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "orden_compra_detalles" ADD COLUMN "acuerdoLineaId" TEXT REFERENCES "acuerdo_suministro_lineas"("id") ON DELETE SET NULL ON UPDATE CASCADE;
